import { tracksTime, type RoleKey } from '@wings/shared';
import type { Database } from '../../db/client.js';
import { timeEntries } from '../../db/schema/index.js';

/**
 * RH/DP time clock entries generated by authentication events.
 *
 * ⚠️ Portaria MTP 671/2021 sign-off from Jurídico is still pending — see
 * docs/timeclock.md. Entries are append-only and always carry their origin.
 */

interface EntryContext {
  employeeId: string;
  role: RoleKey;
  sessionId: string;
  ip?: string | null;
  userAgent?: string | null;
  occurredAt?: Date;
}

async function record(
  db: Database,
  kind: 'clock_in' | 'clock_out',
  source: 'login' | 'logout' | 'session_timeout',
  ctx: EntryContext,
): Promise<boolean> {
  // Admin Master and Diretoria are exempt from the time clock.
  if (!tracksTime(ctx.role)) return false;

  await db.insert(timeEntries).values({
    employeeId: ctx.employeeId,
    occurredAt: ctx.occurredAt ?? new Date(),
    kind,
    source,
    sessionId: ctx.sessionId,
    ip: ctx.ip ?? null,
    userAgent: ctx.userAgent ?? null,
  });
  return true;
}

export function recordLogin(db: Database, ctx: EntryContext): Promise<boolean> {
  return record(db, 'clock_in', 'login', ctx);
}

export function recordLogout(db: Database, ctx: EntryContext): Promise<boolean> {
  return record(db, 'clock_out', 'logout', ctx);
}

/**
 * Closing entry for a session that died of inactivity. `occurredAt` must be the
 * session's last activity, not "now" — the employee stopped working then, and
 * inventing a later time would overstate worked hours.
 */
export function recordSessionTimeout(db: Database, ctx: EntryContext): Promise<boolean> {
  return record(db, 'clock_out', 'session_timeout', ctx);
}
